CREATE TABLE UI_USER_IDENTITY (USER_ID VARCHAR2(64) PRIMARY KEY,CUSTOMER_ID VARCHAR2(64) NOT NULL,STATUS VARCHAR2(32) NOT NULL,ASSURANCE_LEVEL VARCHAR2(16) NOT NULL,CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE TABLE UI_AUTHENTICATOR (AUTHENTICATOR_ID VARCHAR2(36) PRIMARY KEY,USER_ID VARCHAR2(64) NOT NULL,METHOD VARCHAR2(32) NOT NULL,REFERENCE VARCHAR2(256),STATUS VARCHAR2(32) NOT NULL,CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,CONSTRAINT FK_UI_AUTH_USER FOREIGN KEY(USER_ID) REFERENCES UI_USER_IDENTITY(USER_ID));
CREATE TABLE UI_AUTH_TRANSACTION (AUTHENTICATION_ID VARCHAR2(64) PRIMARY KEY,USER_ID VARCHAR2(64) NOT NULL,CLIENT_ID VARCHAR2(128) NOT NULL,PURPOSE VARCHAR2(40) NOT NULL,REQUIRED_LEVEL VARCHAR2(16) NOT NULL,ACHIEVED_LEVEL VARCHAR2(16) NOT NULL,METHOD VARCHAR2(32),STATUS VARCHAR2(32) NOT NULL,AUTHENTICATED_AT TIMESTAMP(6) WITH TIME ZONE,EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,CONSTRAINT FK_UI_TX_USER FOREIGN KEY(USER_ID) REFERENCES UI_USER_IDENTITY(USER_ID));
CREATE INDEX IX_UI_TX_USER ON UI_AUTH_TRANSACTION(USER_ID);
CREATE TABLE UI_AUTH_AUDIT (AUDIT_ID VARCHAR2(36) PRIMARY KEY,AUTHENTICATION_ID VARCHAR2(64),USER_ID VARCHAR2(64),CLIENT_ID VARCHAR2(128),EVENT_TYPE VARCHAR2(64) NOT NULL,METHOD VARCHAR2(32),DETAIL VARCHAR2(1000),CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE INDEX IX_UI_AUDIT_AUTH ON UI_AUTH_AUDIT(AUTHENTICATION_ID);
